import os


class Config:
    # =========================================================================
    # Directories and File Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_3"
    SUBMISSION_DIR = "./submission"

    # Metadata Files (Generated by previous steps)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "validation.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Raw Data Files
    TRAIN_TRACKING_PATH = os.path.join(INPUT_DIR, "train_player_tracking.csv")
    TEST_TRACKING_PATH = os.path.join(INPUT_DIR, "test_player_tracking.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Files
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_PATH = os.path.join(WORKING_DIR, "xgb_model.json")

    # =========================================================================
    # Global Configuration
    # =========================================================================
    SEED = 42
    N_JOBS = 12

    # Temporal Window Configuration
    # Window size 4 means: t-4, t-3, t-2, t-1, t, t+1, t+2, t+3, t+4 (Total 9 frames)
    WINDOW_SIZE = 4

    # Sampling Strategy
    # Undersample negative class (No Contact) to this ratio relative to positive class
    UNDERSAMPLE_RATIO = 10.0

    # =========================================================================
    # Feature Engineering Configuration
    # =========================================================================
    # These features are computed for every timestep in the window.
    # The final feature vector will be a flattened concatenation of these
    # for every step in [t-WINDOW_SIZE, t+WINDOW_SIZE].
    PER_STEP_FEATURES = [
        # --- Player 1 Kinematics ---
        "x_position_p1",
        "y_position_p1",
        "speed_p1",
        "acceleration_p1",
        "sa_p1",
        "sin_direction_p1",
        "cos_direction_p1",
        "sin_orientation_p1",
        "cos_orientation_p1",
        # --- Player 2 Kinematics (or Ground) ---
        "x_position_p2",
        "y_position_p2",
        "speed_p2",
        "acceleration_p2",
        "sa_p2",
        "sin_direction_p2",
        "cos_direction_p2",
        "sin_orientation_p2",
        "cos_orientation_p2",
        # --- Interaction Features ---
        "distance",
        "rel_speed",
        "rel_acceleration",
        "closure_rate",
    ]

    # =========================================================================
    # Model Hyperparameters (XGBoost)
    # =========================================================================
    XGB_PARAMS = {
        "n_estimators": 5000,
        "learning_rate": 0.02,
        "max_depth": 10,  # Deep trees for complex interactions
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "min_child_weight": 10,
        "gamma": 0.1,
        "objective": "binary:logistic",
        "eval_metric": "logloss",  # Monitoring LogLoss
        "tree_method": "gpu_hist",  # Use A100 GPU
        "predictor": "gpu_predictor",
        "random_state": SEED,
        "n_jobs": N_JOBS,
        "scale_pos_weight": 1.0,  # Placeholder, to be tuned or adjusted
    }

    # Training Loop Settings
    EARLY_STOPPING_ROUNDS = 100
    VERBOSE_EVAL = 100

    @classmethod
    def setup(cls):
        """Creates necessary working directories."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
